PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, dob TEXT NOT NULL, gender TEXT NOT NULL CHECK(gender IN ('woman','man','self-described','prefer-not-to-say')), email_verified INTEGER NOT NULL DEFAULT 0, adult_verified INTEGER NOT NULL DEFAULT 0, suspended INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE roles(user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('member','companion','moderator','administrator')), PRIMARY KEY(user_id,role));
CREATE TABLE profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), display_name TEXT NOT NULL, city TEXT NOT NULL DEFAULT '', area TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', languages TEXT NOT NULL DEFAULT '', interests TEXT NOT NULL DEFAULT '', boundaries TEXT NOT NULL DEFAULT '', companion INTEGER NOT NULL DEFAULT 0, visible INTEGER NOT NULL DEFAULT 0, moderation_status TEXT NOT NULL DEFAULT 'pending' CHECK(moderation_status IN ('pending','approved','rejected')), image_key TEXT, updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE consent_records(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), policy TEXT NOT NULL, version TEXT NOT NULL, accepted_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE verification_records(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL, provider_reference TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE auth_tokens(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('verify','reset')), expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings(key,value) VALUES ('male_amount','29900'),('female_amount','0'),('currency','INR'),('tax_configured','false'),('pricing_approved','false');
CREATE TABLE memberships(user_id TEXT PRIMARY KEY REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('active','inactive','pending-policy','revoked')), source TEXT NOT NULL CHECK(source IN ('free','payment','pending')), payment_id TEXT, updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE availability_rules(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), start_minute INTEGER NOT NULL CHECK(start_minute BETWEEN 0 AND 1439), end_minute INTEGER NOT NULL CHECK(end_minute BETWEEN 1 AND 1440), timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata' CHECK(timezone='Asia/Kolkata'), min_notice_hours INTEGER NOT NULL DEFAULT 24, CHECK(end_minute>start_minute));
CREATE TABLE availability_exceptions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), day TEXT NOT NULL, blocked INTEGER NOT NULL DEFAULT 1, UNIQUE(user_id,day));
CREATE TABLE bookings(id TEXT PRIMARY KEY, requester_id TEXT NOT NULL REFERENCES users(id), companion_id TEXT NOT NULL REFERENCES users(id), activity TEXT NOT NULL, start_at INTEGER NOT NULL, end_at INTEGER NOT NULL, buffer_minutes INTEGER NOT NULL DEFAULT 30, venue TEXT NOT NULL, introduction TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','accepted','declined','cancelled','expired','completed','no-show')), expires_at INTEGER NOT NULL, proposed_start_at INTEGER, proposed_end_at INTEGER, proposed_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()), CHECK(end_at>start_at), CHECK(requester_id<>companion_id));
CREATE INDEX bookings_companion_time ON bookings(companion_id,start_at,end_at,status);
CREATE INDEX bookings_requester ON bookings(requester_id,status);
CREATE TRIGGER booking_overlap_insert BEFORE INSERT ON bookings WHEN NEW.status='accepted' BEGIN
 SELECT RAISE(ABORT,'booking_overlap') WHERE EXISTS(SELECT 1 FROM bookings b WHERE b.status='accepted' AND (b.companion_id IN (NEW.companion_id,NEW.requester_id) OR b.requester_id IN (NEW.companion_id,NEW.requester_id)) AND b.start_at < NEW.end_at + NEW.buffer_minutes*60 AND b.end_at+b.buffer_minutes*60 > NEW.start_at);
END;
CREATE TRIGGER booking_overlap_update BEFORE UPDATE ON bookings WHEN NEW.status='accepted' BEGIN
 SELECT RAISE(ABORT,'booking_overlap') WHERE EXISTS(SELECT 1 FROM bookings b WHERE b.id<>NEW.id AND b.status='accepted' AND (b.companion_id IN (NEW.companion_id,NEW.requester_id) OR b.requester_id IN (NEW.companion_id,NEW.requester_id)) AND b.start_at < NEW.end_at + NEW.buffer_minutes*60 AND b.end_at+b.buffer_minutes*60 > NEW.start_at);
END;
CREATE TABLE conversations(id TEXT PRIMARY KEY, booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id), created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX messages_conversation_time ON messages(conversation_id,created_at);
CREATE TABLE payment_orders(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), amount INTEGER NOT NULL CHECK(amount>0), currency TEXT NOT NULL CHECK(currency='INR'), status TEXT NOT NULL CHECK(status IN ('created','captured','failed','refunded','disputed')), created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE UNIQUE INDEX pending_payment_order ON payment_orders(user_id) WHERE status='created';
CREATE TABLE payments(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES payment_orders(id), user_id TEXT NOT NULL REFERENCES users(id), amount INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded_amount INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE webhook_events(id TEXT PRIMARY KEY, event_type TEXT NOT NULL, processed_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE reviews(id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), author_id TEXT NOT NULL REFERENCES users(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, moderation_status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL DEFAULT (unixepoch()), UNIQUE(booking_id,author_id));
CREATE TABLE reports(id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), reported_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE blocks(blocker_id TEXT NOT NULL REFERENCES users(id), blocked_id TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL DEFAULT (unixepoch()), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
CREATE TABLE notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, body TEXT NOT NULL, read_at INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE admin_audit_logs(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE deletion_requests(user_id TEXT PRIMARY KEY REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending', requested_at INTEGER NOT NULL DEFAULT (unixepoch()));
